import sys

# Helper functions
def to_minutes(t: str) -> int:
    h, m = map(int, t.split(":"))
    return h * 60 + m

def to_time(m: int) -> str:
    return f"{m // 60:02d}:{m % 60:02d}"

def complement(busy, work_start=540, work_end=1020):
    """Return free intervals within work hours given busy intervals (sorted, non‑overlapping)."""
    free = []
    cur = work_start
    for s, e in busy:
        if cur < s:
            free.append((cur, s))
        cur = max(cur, e)
    if cur < work_end:
        free.append((cur, work_end))
    return free

def intersect(a, b):
    """Yield overlapping intervals between two interval lists."""
    i = j = 0
    while i < len(a) and j < len(b):
        s = max(a[i][0], b[j][0])
        e = min(a[i][1], b[j][1])
        if s < e:
            yield (s, e)
        if a[i][1] < b[j][1]:
            i += 1
        else:
            j += 1

